def shortest_path(graph, source, target):
    from heapq import heappush, heappop
    from math import inf

    # A queue to store the nodes to be processed, along with the distance from source
    priority_queue = [(0, target, [])]
    # A set to keep track of visited nodes
    visited = set()

    # A dictionary to store the shortest path from source to each node
    distances = {node: inf for node in graph}
    distances[target] = 0

    while priority_queue:
        current_distance, current_node, path = heappop(priority_queue)

        if current_node in visited:
            continue
        visited.add(current_node)

        if current_node == target:
            return (current_distance, path + [current_node])

        for neighbour, weight in graph.get(current_node, []):
            distance = current_distance + weight
            if distance < distances[neighbour]:
                distances[neighbour] = distance
                heappush(priority_queue, (distance, neighbour, path + [current_node]))

    # If target is unreachable
    return (float("inf"), None)

