import heapq       # For using the priority queue
from collections import defaultdict

def shortest_path(graph, source, target):
    # Helper function to get neighbors, weights, and distances
    def get_neighbors(nodes, graph):
        neighbors = {}
        for node in nodes:
            for neighbor, weight in graph[node]:
                if neighbor not in neighbors:
                    neighbors[neighbor] = []
                neighbors[neighbor].append((weight, node))
        return neighbors

    # Helper function to get the next node to process
    def get_next_node(priority_queue, processed):
        while priority_queue:
            distance, node = heapq.heappop(priority_queue)
            if node not in processed:
                return node, distance
        return None, float('inf')

    # Dijkstra's algorithm
    priority_queue = [(0, source)]
    visited = set()
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    path = defaultdict(list)

    while priority_queue:
        current_distance, node = get_next_node(priority_queue, visited)
        if node == target:
            # Reconstruct the path
            path = []
            while node != source:
                path.append(node)
                for neighbor_weight, neighbor in graph[node]:
                    if (neighbor, neighbor_weight) in path:
                        path.append(node)
                        node = neighbor
                        break
            path.append(source)
            path.reverse()
            return distances[target], path

        if current_distance != distances[node]:
            continue

        visited.add(node)

        neighbors = get_neighbors([node], graph)
        for neighbor, neighbor_weight in neighbors[node]:
            if neighbor in visited:
                continue

            new_distance = current_distance + neighbor_weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                path[neighbor].append(node)
                heapq.heappush(priority_queue, (new_distance, neighbor))

    # If target is unreachable
    return float('inf'), None

