from math import inf

def shortest_path(graph, source, target):
    # A dictionary to store the distance from source to each node
    distances = {node: inf for node in graph.keys()}
    distances[target] = 0  # Distance to source is 0

    # A dictionary to store the predecessor of each node for the path reconstruction
    predecessors = {node: None for node in graph.keys()}

    # A priority queue to implement Dijkstra's algorithm
    priority_queue = [(0, source)]

    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        # If we found the target, reconstruct the path
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = predecessors[current_node]
            path.reverse()
            return (current_distance, path)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance_through_current = current_distance + weight

            # Relaxation step: if the new distance is smaller, update the distance and predecessor
            if distance_through_current < distances[neighbor]:
                distances[neighbor] = distance_through_current
                predecessors[neighbor] = current_node
                heappush(priority_queue, (distance_through_current, neighbor))

    # If we exited the loop without finding a path, it means the target is unreachable
    return (float("inf"), None)

