from heapq import heappush, heappop
import math

def shortest_path(graph, source, target):
    # Priority queue for BFS, using a tuple (distance, node) for priority
    queue = [(0, source)]
    # Dictionary to store the shortest distance to each node from the source
    distance = {source: 0}
    # Dictionary to store the previous node on the shortest path from the source to each node
    previous = {source: None}
    # Dictionary to store the path from target to source
    path = {target: []}

    while queue:
        current_distance, current_node = heappop(queue)

        # If we reach the target node, reconstruct the path
        if current_node == target:
            path_reconstructed = []
            while current_node is not None:
                path_reconstructed.append(current_node)
                current_node = previous[current_node]
            path_reconstructed.reverse()
            return (current_distance, path_reconstructed)

        # If the current node is already visited, skip it
        if current_node in distance and current_distance > distance[current_node]:
            continue

        # Mark the current node as visited
        distance[current_node] = current_distance
        for neighbor, weight in graph.get(current_node, []):
            new_distance = current_distance + weight
            if neighbor not in distance or new_distance < distance[neighbor]:
                heappush(queue, (new_distance, neighbor))
                distance[neighbor] = new_distance
                previous[neighbor] = current_node
                # If we are reconstructing the path for the target node, update the path list
                if neighbor == target:
                    path[neighbor] = path.get(neighbor, []) + [current_node]

    # If no path to the target is found, return infinity and None
    return (math.inf, None)

